import {resourceCandidates} from './resource-hints.js';
import * as G from './survival.js';
import {RIFT_REALMS,COMPANIONS,MODULES,RIFT_EVENTS,ROUTES,LEVEL_CO_TEXT,puzzleTarget,hasModule,inRift,highTide} from './symbiosis.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const items=bag=>Object.entries(bag||{}).map(([k,n])=>(G.ITEMS[k]?.name||k)+' ×'+n).join('、')||'无需材料';
const btn=(action,id,text,value='',disabled=false)=>`<button class="secondary" data-co="${action}" data-co-id="${id}" data-co-value="${value}" ${disabled?'disabled':''}>${text}</button>`;
const card=(title,body,cls='')=>`<article class="co-card ${cls}"><h3>${title}</h3>${body}</article>`;
export function renderCoexist(s,tab='expedition',selected){
 const e=s.symbiosis,r=e.run,n=s.nodes.find(n=>n.id===selected),camp=G.inHome(s)&&G.nearby(s,'campfire',220);
 let body=`<nav class="co-tabs">${Object.entries({expedition:'裂隙远征',companions:'营地伙伴',modules:'装备模块',projects:'九级共建',history:'见闻与回信'}).map(([id,text])=>`<button data-co-tab="${id}" class="${tab===id?'selected':''}">${text}</button>`).join('')}</nav>`;
 if(n?.type==='riftanchor'&&r){const i=n.anchor,t=puzzleTarget(r,i),target=t.map((v,k)=>v?k+1:null).filter(Boolean),h=r.hints[i];
 body+=card('观测点 '+(i+1)+' · '+(r.realm==='tide'?'潮闸校准':'风路接续'),`<p>${r.realm==='tide'?'刻度指向两条进水道，剩余一条需要关闭。':'避难所需要两条清洁风路，孢子支路必须关闭。'}碑文写着「${['东','中','西'][(r.seed>>>i)%3]}路勿通」。按钮依次为东、中、西。</p><div class="co-switches">${r.switches[i].map((v,k)=>btn('anchor-toggle',n.id,(k+1)+' · '+['东','中','西'][k]+' '+(v?'开':'关'),String(k),r.anchors[i])).join('')}</div>${btn('anchor-check',n.id,r.anchors[i]?'已完成，奖励仅一次':'检验回路','',r.anchors[i])}${btn('anchor-hint',n.id,'提示 '+h+'/3','',h===3)}<p class="co-hint">${h===0?'先阅读碑文；错误尝试不消耗材料。':h===1?'三条路中只开两条，方位与按钮编号对应。':h===2?'碑文指出的是必须关闭的那一条。':'解法：开启 '+target.join('、')+' 号，关闭其余阀门。'}</p>${i===2?btn('pacify',n.id,'和平修复守卫 · 4 专属材料＋3 石料/荧光花','',!r.anchors.every(Boolean)):''}<p>打开面板时整个世界暂停，关闭后才继续潮汐、战斗与生产。</p>`);
 }
 if(n?.type==='riftevent'&&r){const def=RIFT_EVENTS.find(v=>v.id===n.eventId);body+=card(def.name,`<p>${def.text}</p>${def.options.map(o=>`<div class="co-choice"><b>${o.name}</b><p>投入：${items(o.cost)}<br>带回：${items(o.drop)} · 生态 ${o.eco>=0?'+':''}${o.eco}<br>后续回信：${items(o.future)}</p>${btn('event',n.id,e.run.choices[n.eventId]?'已作出选择':'选择这一方案',o.id,!!r.choices[n.eventId])}</div>`).join('')}`);}
 if(tab==='expedition'){
  if(r){const percent=r.anchors.filter(Boolean).length;body+=card(RIFT_REALMS[r.realm].name+' · '+ROUTES[r.template].name,`<p>种子 <b>${r.seed}</b> · ${r.deep?'深层':'普通'} · ${r.weather}<br>观测点 ${percent}/3 · 远征已进行 ${Math.floor(r.elapsed/60)} 分 ${Math.floor(r.elapsed%60)} 秒<br>${r.realm==='tide'?(highTide(s)?'涨潮：中线仅保留窄栈道，北侧高架路始终通行。':'退潮：中线捷径可以通行。'):'未净化区域持续侵蚀生命和意识；先找通风观测点。'}</p><div class="co-targets">${s.nodes.filter(n=>['riftanchor','riftevent','wormhole'].includes(n.type)).map(n=>`<button data-co-walk="${n.id}">${n.type==='wormhole'?'↩ 免费回程':n.type==='riftanchor'?(r.anchors[n.anchor]?'✓ ':'◇ ')+'观测点 '+(n.anchor+1):'✧ '+RIFT_EVENTS.find(v=>v.id===n.eventId).name}</button>`).join('')}</div><p>点击目标会走近并打开地点。入口返回保留全部收获；紧急救援损失普通材料的 ${hasModule(s,'salvage')?15:30}%，图纸、纪念章、装备与食物保留。</p><button class="danger" data-co-rescue>查看紧急救援</button>`);}
  else{body+=`<div class="co-intro"><h3>准备一次有归路的远行</h3><p>3 级开启潮汐群岛，4 级开启地心菌窟。每次出发消耗 3 木材＋1 旅行口粮。带好石斧、石镐、食物与光源。目标与奖励生成后固定，随时保存继续。</p><label>分享种子（留空自动生成）<input id="co-seed" inputmode="numeric" maxlength="10" placeholder="0—4294967295" aria-label="远征种子"></label>${btn('deep','','深层远征 '+(e.deep?'开':'关'),' ',s.level!==9)}<p>${camp?'已在原岛营火旁，可以准备出发。':'先返回原岛营火附近，邀请伙伴或整理模块。'}</p></div><div class="co-grid">${Object.entries(RIFT_REALMS).map(([id,d])=>card(d.name,`<p>${d.tip}</p><small>${d.level} 级 · 三种路线 · 每次三段随机见闻</small>${btn('depart',id,'准备出发','',!camp||s.level<d.level)}`)).join('')}</div>`;}
  body+=`<p class="co-note">可建临时营火、庇护所、净化器和蓄水井。离开裂隙后临建设施不保留；永久营地建在六张常驻地图。天气、孢子与岗位均不离线运行。</p>`;
 }
 if(tab==='companions')body+=`<p>${camp?'在营火旁商量招募、随行和工作。':'招募、切换随行与岗位需要原岛营火。'}最多一名伙伴随行；其他伙伴夜间休息。岗位在五级解锁，投入真实材料，产物目标库存 20，当前原岛运行时才工作。</p><div class="co-grid">${Object.entries(COMPANIONS).map(([id,d])=>{const c=e.companions[id],b=s.buildings.find(b=>b.type===d.station);return card(d.name,`<div class="co-portrait" style="--co-color:${d.color}">✦</div><p>${d.intro}</p><p><b>随行能力：</b>${d.perk}</p>${c?`<p>${e.following===id?'与你同行':c.job?'岗位已安排':'休息中'} · 累计完成 ${c.produced} 批</p>${btn('follow',id,e.following===id?'留在营地':'邀请随行','',!camp)}${btn('job',id,c.job?'暂停岗位':'安排'+d.job,'',!camp||s.level<5)}<p>工作站：${G.BUILDING_NAMES[d.station]}<br>每批：${items(d.input)} → ${(Object.keys(d.output).length?items(d.output):'维修工具')}${id==='engineer'?'（工具恢复 20 耐久）':''}<br>${b?'岗位库存：'+items(b.inventory):'尚未建造岗位'}<br>${b?.coTask?'加工剩余 '+Math.ceil(b.coTask.remaining)+' 秒':'缺少投入或达到目标时停止'}</p>${b?btn('supply',b.id,'投入一批材料')+btn('collect',b.id,'领取岗位库存')+`<button data-co-walk="${b.id}">走到岗位</button>`:''}<details><summary>${d.story}${c.story?' ✓':''}</summary><p>${c.story?d.storyText:'完成一次裂隙观测，带回 '+items(d.storyCost)+'，听听伙伴的故事。'}</p>${btn('story',id,'交付物资，记录故事','',!camp||c.story)}</details>`:`<p>${d.level} 级 · 邀请物资：${items(d.cost)}</p>${btn('recruit',id,'邀请来到营地','',!camp||s.level<d.level)}`}`);}).join('')}</div>`;
 if(tab==='modules')body+=`<p>探索装备、当前武器、投影臂各有两个模块槽。在原岛营火旁免费拆换，已研发图纸不会丢失。效果可搭配，武器专长继续生效。</p>${Object.entries({gear:'探索装备',weapon:'当前武器',arms:'投影臂'}).map(([slot,name])=>`<h3>${name} · ${e.loadout[slot].length}/2</h3><div class="co-grid">${Object.entries(MODULES).filter(([,m])=>m.slot===slot).map(([id,m])=>card(m.name+` <small>${m.level} 级</small>`,`<p>${m.text}</p><p>研发：${items(m.cost)}</p>${e.unlocked.includes(id)?btn('module-equip',id,e.loadout[slot].includes(id)?'✓ 已装配 · 拆下':'安装模块','',!camp):btn('module-unlock',id,'研发模块','',!camp||s.level<m.level)}`)).join('')}</div>`).join('')}`;
 if(tab==='projects')body+=`<div class="co-growth">${LEVEL_CO_TEXT.slice(1).map((t,i)=>`<p class="${s.level===i+1?'current':''}"><b>${i+1} · ${G.LEVEL_NAMES[i+1]}</b><span>${t}</span></p>`).join('')}</div><h3>七级 · 修复世界</h3><p>完成裂隙三处观测、建好对应原岛设施后，才能交付项目物资。水系需要 8 潮汐晶砂＋4 芦果；菌群需要 8 孢囊＋4 种子。</p>${btn('project','water',e.projects.includes('water')?'✓ 水系恢复':'修复水系','',e.projects.includes('water'))}${btn('project','spores',e.projects.includes('spores')?'✓ 菌群共生':'修复菌群','',e.projects.includes('spores'))}<h3>八级 · 六地协作</h3><p>先完成两项修复、取得当地营地同意。工程物资：2 晶砂＋2 木板；生态物资：2 孢囊＋2 芦果。每地交付一次。</p><div class="co-grid">${['home','verdant','cinder','frost','mirror','orbit'].map(id=>card(G.REALMS[id].name,`<p>${e.signals.includes(id)?'✓ 已完成协调':Object.hasOwn(s.odyssey.contacts,id)?'已取得营地同意':'先到当地完成营地约定'}</p>${btn('signal',id,'工程物资','craft',e.signals.includes(id))}${btn('signal',id,'生态物资','care',e.signals.includes(id))}`)).join('')}</div><h3>九级 · 留下自己的世界</h3><p>完成深层远征 ${e.endless} 次。深层模式在远征页切换，守卫与环境扰动更危险；图纸和纪念章用于模块与八种营地装饰。旧存档无需重练等级。</p>`;
 if(tab==='history')body+=card('营地邮袋',`<p>${items(e.mail)}</p>${btn('claim','','领取奖励与回信','',!camp)}`)+e.history.map(h=>card(RIFT_REALMS[h.realm].name+' · 种子 '+h.seed,`<p>${ROUTES[h.template].name} · 观测 ${h.anchors}/3 · ${h.guardian?'守卫安定':'尚未处理守卫'} · ${h.emergency?'紧急救援':'平安归来'} · ${Math.floor(h.elapsed/60)} 分钟</p>${Object.entries(h.choices).map(([id,choice])=>{const d=RIFT_EVENTS.find(v=>v.id===id);return'<p><b>'+d.name+'</b> · '+d.options.find(v=>v.id===choice).later+'</p>';}).join('')}<small>同版本、同种子与同模式可分享路线；不会上传完整存档。</small>`)).join('');
 return{title:'共生远征',subtitle:'3.0 · 每一次归来，让营地和世界改变一点',body};
}
export function materialSources(s,recipe){return Object.entries(recipe.cost).filter(([id,n])=>G.craftAmount(s,id)<n).map(([id,n])=>{const nodes=Object.entries(G.NODES).filter(([,d])=>d.drop?.[id]);const local=resourceCandidates(s,id,G.NODES)[0];const r=G.RECIPES.find(r=>r.item===id);return{item:id,missing:n-G.craftAmount(s,id),node:local,source:local?G.NODES[local.type].name+' · '+Math.round(G.distance(s.player,local))+' 步':nodes.length?nodes.map(([,d])=>d.name+(d.tool?'（需'+G.ITEMS[d.tool].name+'）':'')).join(' / '):r?'合成「'+r.name+'」':id==='blueprint'?'裂隙观测结算与事件回信':id==='resonance'?'荧光花在营火冥想':'查看生存手册与远征见闻'};});}
